import{_ as i,c as t,aU as a,a as l}from"./chunks/framework.DP-R0N-M.js";const g=JSON.parse('{"title":"数据库","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/数据库.md","filePath":"note/back-end/mianshi/数据库.md","lastUpdated":1758205906000}'),n={name:"note/back-end/mianshi/数据库.md"};function e(h,s,r,d,o,p){return l(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h1><h2 id="事务的四大特性-acid" tabindex="-1">事务的四大特性-ACID <a class="header-anchor" href="#事务的四大特性-acid" aria-label="Permalink to &quot;事务的四大特性-ACID&quot;">​</a></h2><p>事务（Transaction）是确保数据一致性和完整性的重要机制。事务的四大特性——原子性（Atomicity）、一致性（Consistency）、隔离性（Isolation）和持久性（Durability），简称 ACID，是数据库事务处理的核心原则。</p><h2 id="事务的隔离级别" tabindex="-1">事务的隔离级别 <a class="header-anchor" href="#事务的隔离级别" aria-label="Permalink to &quot;事务的隔离级别&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">隔离级别</th><th style="text-align:left;">脏读</th><th style="text-align:left;">不可重复读</th><th style="text-align:left;">幻读</th></tr></thead><tbody><tr><td style="text-align:left;">读未提交（Read uncommitted）</td><td style="text-align:left;">×(未解决)</td><td style="text-align:left;">×</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">读已提交（Read committed）</td><td style="text-align:left;">√(解决)</td><td style="text-align:left;">×</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">可重复读（Repeatable read）</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">可串行化（Serializable）</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td></tr></tbody></table><p>脏读: 读取到未提交的事务数据</p><p>不可重复读: 同一事务内多次读取同一行数据时，因其他事务修改该行数据并提交，导致读取结果不一致。例如：事务A两次读取用户年龄，第一次为20岁，第二次因事务B修改变成22岁。‌</p><p>幻读‌：同一事务内多次执行相同范围查询时，因其他事务插入或删除符合条件的数据，导致结果集数量不一致。例如：事务A统计年龄&gt;20的用户数，第一次为3条，第二次因事务B插入新用户变为4条。‌</p><h2 id="mvcc" tabindex="-1">MVCC <a class="header-anchor" href="#mvcc" aria-label="Permalink to &quot;MVCC&quot;">​</a></h2><p>MVCC叫多版本并发控制，是一种通过保存数据的历史版本来实现并发访问的技术。它的核心目的是让读操作和写操作可以互不阻塞，从而提升数据库的并发性能</p><ul><li>mvcc的核心是快照读</li><li>undo log 是历史版本的支撑（最主要的是里面会存储当前事务的xid和数据和上一个事务的xid，如果回滚的话就可以找到上一个事务的完整数据了）</li><li>readview 决定谁能看到那个版本 （readview里面存放的有正在进行的事务，还有已经执行的完的事务，这就可以解释，为啥同一个事务中可以获取到最新的未提交事务的数据）</li></ul><h2 id="数据库的log日志" tabindex="-1">数据库的log日志 <a class="header-anchor" href="#数据库的log日志" aria-label="Permalink to &quot;数据库的log日志&quot;">​</a></h2><h4 id="_1-binlog-二进制日志" tabindex="-1">1. Binlog (二进制日志) <a class="header-anchor" href="#_1-binlog-二进制日志" aria-label="Permalink to &quot;1. Binlog (二进制日志)&quot;">​</a></h4><ul><li><strong>是什么？</strong> Binlog 是 <strong>MySQL Server 层</strong> 实现的、记录所有更改数据库数据的 DDL（如CREATE/ALTER）和 DML（如INSERT/UPDATE/DELETE）操作的<strong>逻辑日志</strong>。</li><li><strong>特点：</strong><ul><li><strong>逻辑日志：</strong> 记录的是操作的逻辑内容，比如<code>UPDATE user SET name = &#39;Alice&#39; WHERE id = 1;</code>，或者是行变更前后的完整镜像（取决于格式）。</li><li><strong>追加写入：</strong> 以“追加”的方式写入文件，不会覆盖以前的日志。</li><li><strong>用途广泛：</strong> <strong>数据恢复</strong>。</li></ul></li></ul><h4 id="_2-undo-log-回滚日志" tabindex="-1">2. Undo Log (回滚日志) <a class="header-anchor" href="#_2-undo-log-回滚日志" aria-label="Permalink to &quot;2. Undo Log (回滚日志)&quot;">​</a></h4><ul><li><strong>是什么？</strong> Undo Log 是 <strong>InnoDB 存储引擎层</strong> 独有的、用于保证<strong>事务原子性</strong> 和<strong>多版本并发控制（MVCC）</strong> 的<strong>物理逻辑日志</strong>。</li><li><strong>特点：</strong><ul><li><strong>物理逻辑日志：</strong> 它记录的是数据被修改<strong>之前</strong>的旧版本状态（旧数据的拷贝）。例如，你更新了一行数据，Undo Log 会记录这行数据更新前的内容。</li><li><strong>循环使用：</strong> Undo Log 存储在特殊的回滚段（Rollback Segments）中，会被循环覆盖。当没有事务再需要读取某个旧版本数据时，对应的 Undo Log 空间就可以被回收。</li><li><strong>核心用途：</strong> 用于<strong>事务回滚</strong> 和实现 <strong>MVCC</strong>（实现读已提交和可重复读隔离级别）。</li></ul></li></ul><hr><h2 id="命中索引还是很慢" tabindex="-1">命中索引还是很慢 <a class="header-anchor" href="#命中索引还是很慢" aria-label="Permalink to &quot;命中索引还是很慢&quot;">​</a></h2><p>可能出现的原因：</p><ol><li>索引建的有问题，索引字段区分不大。</li><li>虽然命中索引，但是回表很慢，可能字段太多或者数据量太大。<strong>解决：</strong> 覆盖索引，建立一个包含所有查询字段的复合索引</li><li>深度分页。<strong>解决：</strong> 利用 id 区间来查询分页</li></ol><h2 id="什么是聚簇索引和非聚簇索引" tabindex="-1">什么是聚簇索引和非聚簇索引 <a class="header-anchor" href="#什么是聚簇索引和非聚簇索引" aria-label="Permalink to &quot;什么是聚簇索引和非聚簇索引&quot;">​</a></h2><p>在InnoDB存储引擎中，根据索引的存储形式，又可以分为以下两种：</p><p>聚簇索引： 索引即数据，数据行直接存储在索引树的叶子节点上，主键就是聚簇索引，InnoDB中一个表只能有一个聚簇索引</p><p>非聚簇索引：索引是路由，叶子节点只存储指向数据行位置的指针。普通索引、组合索引、唯一索引都属于非聚簇索引</p><h2 id="mysql什么情况下会发生死锁现象" tabindex="-1">mysql什么情况下会发生死锁现象 <a class="header-anchor" href="#mysql什么情况下会发生死锁现象" aria-label="Permalink to &quot;mysql什么情况下会发生死锁现象&quot;">​</a></h2><h3 id="什么是死锁" tabindex="-1">什么是死锁？ <a class="header-anchor" href="#什么是死锁" aria-label="Permalink to &quot;什么是死锁？&quot;">​</a></h3><p>死锁是指两个或两个以上的事务在执行过程中，因争夺锁资源而造成的一种互相等待的现象。若无外力干涉，它们都将无法进行下去。</p><p>核心条件：双方都持有了对方需要的锁，同时又等待对方释放锁。</p><h3 id="什么情况下会发生死锁" tabindex="-1">什么情况下会发生死锁？ <a class="header-anchor" href="#什么情况下会发生死锁" aria-label="Permalink to &quot;什么情况下会发生死锁？&quot;">​</a></h3><p>死锁通常发生在并发事务对<strong>多个不相干的对象</strong>（行、表）以<strong>不同的顺序</strong>进行加锁时。</p><p><strong>经典例子：并发转账</strong></p><p>假设有一张账户表 <code>accounts</code>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">id</th><th style="text-align:left;">name</th><th style="text-align:left;">balance</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">Alice</td><td style="text-align:left;">1000</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">Bob</td><td style="text-align:left;">500</td></tr></tbody></table><p>两个并发事务执行如下操作：</p><p><strong>事务 T1</strong>：Alice 给 Bob 转账 100</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 持有id=1的行锁</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 请求id=2的行锁，等待T2释放</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>事务 T2</strong>：Bob 给 Alice 转账 50</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 持有id=2的行锁</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 请求id=1的行锁，等待T1释放</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>此时：</p><ul><li><strong>T1</strong> 持有 <code>id=1</code> 的锁，等待 <code>id=2</code> 的锁。</li><li><strong>T2</strong> 持有 <code>id=2</code> 的锁，等待 <code>id=1</code> 的锁。</li></ul><p>双方互相等待，<strong>死锁</strong>发生。MySQL的InnoDB引擎会自动检测到死锁，并<strong>强制回滚其中一个事务</strong>（通常是较小的事务，即影响行数较少的事务），让另一个事务成功执行。</p><hr><h3 id="如何排查死锁" tabindex="-1">如何排查死锁？ <a class="header-anchor" href="#如何排查死锁" aria-label="Permalink to &quot;如何排查死锁？&quot;">​</a></h3><ol><li>查看error日志。确认 innodb_print_all_deadlocks 配置是否为 ON（默认通常开启），可以直接在MySQL的错误日志文件中搜索 &quot;deadlock&quot; 关键字，查看历史死锁记录。</li><li>使用 <code>SHOW ENGINE INNODB STATUS</code> 命令,这是最直接、最常用的方法 <strong>重点看这部分内容</strong>： <ul><li><strong>TRANSACTION 1</strong> 和 <strong>TRANSACTION 2</strong>：两个事务的信息。</li><li><strong>WAITING FOR THIS LOCK</strong>：某个事务在等待什么锁（锁的类型、锁在哪一行或哪个索引上）。</li><li><strong>HOLDS THE LOCK</strong>：某个事务当前持有什么锁。</li><li>根据这些信息，就能清晰地还原死锁现场。</li></ul></li></ol><h3 id="如何解决和避免死锁" tabindex="-1">如何解决和避免死锁? <a class="header-anchor" href="#如何解决和避免死锁" aria-label="Permalink to &quot;如何解决和避免死锁?&quot;">​</a></h3><ul><li>无需过多操作,InnoDB已自动回滚其中一个事务，另一个事务会继续执行</li><li>保持事务小巧并尽快提交：缩短事务执行时间，减少锁的持有时间。</li><li>注意加锁顺序</li><li>为查询创建合适的索引，避免升级表锁，大大增加死锁概率。</li></ul>`,46)])])}const c=i(n,[["render",e]]);export{g as __pageData,c as default};
